/**
 * Pod Explainer Generator
 *
 * Generates the Stage-1 "explainer" payload for each listening pod sentence:
 *   - explainer_decomposition: ordered chunk-pairs [{chunk_target, chunk_known}, ...]
 *   - explainer_text:         narration string for xAI multilingual TTS
 *
 * Stage-1 sequence per sentence (player-side):
 *     target → known → explainer → target → target
 *
 * Stage-1 only. Subsequent stages skip the explainer slot. Audio is
 * generated by a downstream pass once explainer_text is populated.
 *
 * Architecture:
 *   - Decomposition + narration are produced by Haiku (via the existing
 *     claude-cli.cjs helper — Max Plan, not the API). Per-sentence call.
 *   - Connector word ("means", "significa", "veut dire", ...) localises
 *     from the course's `_for_<lang>` half.
 *   - Writes are routed through Supabase service-role client; the caller
 *     (admin endpoint) is responsible for auth + batching.
 *
 * Skipped courses (config-side, baked into one place so they can't drift):
 *   - cym, cym_n, cym_s — Welsh has TTS voice quality blocker.
 *   - hrv_for_eng — pod-0 still atomised; explainers would target the
 *     atomised rows and be wasted work when the merge-and-regen happens.
 */

const { claudeChat } = require('./shared/claude-cli.cjs')

// =============================================================================
// CONNECTOR LOCALISATION
// =============================================================================
//
// The connector phrase joins chunk-target with chunk-known in the narration.
// Example narration for Italian-for-English: "buona means good, sera means
// afternoon, come stai means how are you doing".
//
// Localised per learner language (the second half of course_code: e.g.
// `ita_for_eng` → "eng" → "means"). Falls back to "means" for unknown.
// We could let Haiku pick it, but pinning it here keeps the narration
// consistent across the catalogue and removes a class of LLM variance.

const CONNECTOR_BY_LEARNER_LANG = {
  eng: 'means',
  spa: 'significa',
  fra: 'veut dire',
  ita: 'significa',
  por: 'significa',
  deu: 'bedeutet',
  nld: 'betekent',
  jpn: 'は ... という意味です', // handled differently in prompt (postfix construction)
  zho: '意思是',
  kor: '의 뜻은',
  ara: 'يعني',
  tur: 'demek',
  pol: 'oznacza',
  rus: 'означает',
}

function getConnectorForLearnerLang(learnerLang) {
  return CONNECTOR_BY_LEARNER_LANG[learnerLang] || 'means'
}

function parseCourseCode(courseCode) {
  // "ita_for_eng" → { target: "ita", learner: "eng" }
  // "fra_ca_for_eng" → { target: "fra_ca", learner: "eng" }
  // "eng_for_jpn" → { target: "eng", learner: "jpn" }
  const m = String(courseCode).match(/^(.+)_for_(.+)$/)
  if (!m) return { target: courseCode, learner: 'eng' }
  return { target: m[1], learner: m[2] }
}

// =============================================================================
// SKIP RULES
// =============================================================================

const SKIPPED_TARGET_LANGS = new Set(['cym', 'cym_n', 'cym_s'])

function shouldSkipCourse(courseCode) {
  const { target } = parseCourseCode(courseCode)
  if (SKIPPED_TARGET_LANGS.has(target)) return { skip: true, reason: 'welsh-tts-blocker' }
  // hrv_for_eng was protected while Aran's hand-authored pod was in live use;
  // canon v2 (2026-06-10) supersedes it — Tom: "re-do Croatian as well now".
  return { skip: false }
}

// =============================================================================
// PROMPT BUILDING
// =============================================================================

/**
 * Build the Haiku prompt to produce decomposition + narration for a BATCH
 * of sentences. The CLI startup cost is ~2-15s per invocation regardless
 * of payload size, so we amortise it by handling many sentences per call.
 *
 * Returns a prompt that asks the model to emit a strict JSON array, one
 * entry per input sentence, in the same order:
 *   [
 *     { "id": "<echo>", "decomposition": [...], "explainer_text": "..." },
 *     ...
 *   ]
 *
 * Chunks are ATOM-sized (Tom 2026-06-12, from Aran's explainer guide):
 * the smallest piece that carries meaning alone — usually one word. Glue
 * words attach to their neighbour ("na posao"); fixed expressions stay
 * whole ("come stai"); a clause is never one chunk. Clause-level pairing
 * returns later as the FINAL rung of the Stage-0 ladder, not as the
 * default decomposition.
 */
function buildBatchPrompt({ sentences, targetLang, learnerLang, connector }) {
  const inputBlock = sentences
    .map((s, i) => `${i + 1}. id=${JSON.stringify(s.id)}  target=${JSON.stringify(s.target_text)}  known=${JSON.stringify(s.known_text)}`)
    .join('\n')
  return `You are writing a one-time spoken "explainer" for a language-learning app.
Target language: ${targetLang}
Learner language: ${learnerLang}

This explainer fires ONCE, the first time a learner meets a target sentence. It
sits between the target audio and its meaning. It must be SHORT and
NON-INTERRUPTIVE — a quick, friendly "here's how this breaks down". Never a
grammar lesson with TERMINOLOGY — but its whole PURPOSE is to reveal what the
target language is DOING with its grammar: when the target builds a phrase
differently from the known language (different word order, an object stranded
after an adverb, a "have" where English has "be"), that divergence is THE THING
TO SHOW, in plain words — keep the diverging pieces together and say what it
does literally. The learner wants to understand how the language assembles
meaning, not just what the words add up to.

For EACH sentence below produce a JSON object with:

  "id"            — echo the input id
  "decomposition" — ordered array of chunk objects (see below), or []
  "explainer_text"— the SPOKEN narration string (the only thing turned into
                    audio), or "" if no explainer is warranted

Each chunk object in "decomposition" has:
  "chunk_target"  — ONE ATOM: the smallest piece that has an HONEST, NATURAL
                    known-language gloss. The governing test is GLOSSABILITY +
                    COGNITIVE LOAD, not minimal size — do NOT shred to single
                    syllables. An atom may be SEVERAL WORDS when that is what
                    glosses cleanly: "tú ag dul" = "you're going", "go raibh
                    maith agat" = "thank you", "come stai" = "how are you". If a
                    piece's only honest isolated gloss is awkward, empty, or a
                    bare grammar-word ("are", "to", a particle), MERGE IT UP
                    into the neighbouring chunk that DOES gloss cleanly rather
                    than glossing it alone. These exercises repeat many times,
                    so err toward slightly larger, cleanly-glossable chunks over
                    maximal fragmentation. Still bounded ABOVE: a chunk must
                    stay small enough to learn as one unit — a whole clause or a
                    long verb phrase is too big; split it at the next clean
                    gloss seam.
                    WORD-ORDER DIVERGENCE OVERRIDES THE MERGE-UP DEFAULT: when a
                    thin piece is thin because the target REORDERS it (an object
                    pronoun stranded after an adverb, a verb thrown to the end),
                    do NOT strand it and do NOT silently absorb it — KEEP the
                    reordered span together as one chunk, gloss it for MEANING,
                    and put the literal order in "literal" so the note can show
                    what the language did. e.g. Irish "ar ball thú" → chunk_known
                    "you later", literal "later you" (the explainer then says
                    "...— literally 'later, you'"). Showing that reorder is the
                    whole point; never split it into "ar ball = later" + a
                    stranded "thú = you".
                    THE SAME RULE COVERS "HAVE" SAID AS "BE + AT-ME" and every
                    prepositional-pronoun construction: keep the WHOLE
                    construction together, gloss the MEANING, put the structure
                    in "literal". Irish "tá lá gnóthach agam" → chunk_known
                    "I've got a busy day", literal "there's a busy day at me" —
                    NEVER split off "agam" as a thin "for me"/"at me". (When the
                    prepositional pronoun is already swallowed by an idiom, e.g.
                    "tá súil agam" = "I hope", it just stays inside, no literal
                    needed.) Be CONSISTENT within a sentence: if "tá súil agam"
                    is whole, "tá lá gnóthach agam" is whole too.
  "chunk_known"   — its known-language gloss, following the CALIBRATED RULE below
  "primitives"    — OPTIONAL array of finer {target, known} word-pieces inside
                    this chunk, INCLUDING form-as-job glosses (see rule). Omit
                    when the chunk is already a single word. This is structured
                    data for later use; it is NOT all spoken.
  "literal"       — OPTIONAL assembled word-by-word reading of the chunk, e.g.
                    "from Split I am". Include whenever this chunk's internal
                    order would MISLEAD (see rule). MULTIPLE chunks may EACH
                    carry a literal — this is STRUCTURED data (it becomes a
                    per-atom note downstream), and it is NOT all spoken. The
                    spoken "explainer_text" stays clean and carries AT MOST ONE
                    tail no matter how many chunks have a literal.

================  THE CALIBRATED RULE (follow exactly)  ================

1. DEFAULT narration is just glosses joined by "${connector}":
     "X ${connector} Y, Z ${connector} Q"
   Say each meaningful target chunk, then its meaning. Natural punctuation.

2. FORM-DOES-A-JOB. When a word's grammatical FORM carries the meaning, gloss
   it AS that job in plain English — never name the grammar.
     rajčica  → "of tomatoes"      (NOT "tomatoes (genitive)")
     veliku   → "large"            (just the meaning; the ending is silent)
   Put any finer form-job pieces in "primitives", but keep "chunk_known" plain.

3. "SO / LITERALLY" TAIL — this is where the explainer DOES ITS JOB of showing
   what the language is doing; fire it WHENEVER the word-by-word order would
   mislead about how the phrase is built, and not otherwise. That covers
   have-for-be, "call yourself"-style reflexives, verb-on-the-end orders, and
   OBJECT-STRANDING (a pronoun thrown past an adverb). It does NOT cover mild
   reordering that still reads fine (e.g. "for me, a kir"): leave those bare.
   Frequency follows the language — a heavily-reordering language (Irish, German,
   Japanese) earns more tails than a closely-matching one; don't force them, but
   don't suppress a genuine construction either.
     "Iz Splita sam"  → "...sam ${connector} I am — so 'from Split I am'"
     "ar ball thú"    → "ar ball thú ${connector} you later — so 'later, you'"
     "molim"          → "please — literally 'I ask'"
   If reading the pieces in order is clear, NO tail. Most lines have none.
   CRITICAL SEPARATION — the spoken "explainer_text" vs the structured "literal"
   fields are DIFFERENT channels and must not be conflated:
   • Put EVERY diverging chunk's literal in its OWN chunk's "literal" field
     (there can be several per row; they become per-atom notes downstream).
   • "explainer_text" is the clean spoken narration: each chunk + its gloss,
     in order, ONCE. It carries AT MOST ONE "so/literally" tail for the WHOLE
     row — the single most illuminating construction — at the VERY END, never
     mid-narration. Do NOT echo a chunk twice. Do NOT pour every literal into
     explainer_text. A 3-sentence row is still ONE clean pass with ≤1 tail.

4. REGISTER FLAG — one word, only when it matters. If the target is marked
   formal/polite (e.g. the vous / -ste / formal-or-plural form), append the
   single word "politely" to that chunk's gloss. Do NOT explain the alternative,
   do NOT say "you'd say X to a friend". Just the flag.

5. FIXED SINGLE-WORD EXPRESSIONS. Some targets are one fixed word with no clean
   word-gloss (e.g. "Izvolite"). Do NOT force a decomposition and do NOT drop
   it. Instead give a ONE-LINE USAGE note as the explainer_text, and put a
   single chunk in decomposition whose chunk_known IS that usage note:
     "Izvolite" → explainer_text:
       "Izvolite — a waiter's polite 'go ahead, what'll it be?'"
   Keep it to one short, natural line.

6. PROPER NOUNS — names of people, places, brands — are NOT translated and NOT
   explained. Drop them from the decomposition entirely ("Split ${connector}
   Split" is noise; "Karlovačko" is a beer brand, leave it).

7. WHEN TO SKIP — RARE. After dropping proper nouns, skip (return [] and "")
   ONLY when at most ONE ordinary meaningful chunk remains AND it is NOT a
   fixed expression needing a usage note — the target/known pair already says
   everything. A sentence with TWO OR MORE meaningful chunks must ALWAYS be
   decomposed and narrated, however simple or familiar it looks — whether the
   learner has met a chunk before is handled downstream, never by you. (A bare
   one-word line like "molim?" on its own still earns a tiny gloss IF its form
   would mislead per rule 3; otherwise skip.)

8. NEVER use grammar terms (genitive, accusative, reflexive, dative,
   nominative, conjugation, declension...). NO asides. NO alternatives. NO
   "you could also say". Short, plain, kind, once.

================  GRANULARITY CALIBRATION (match this exactly)  ================

This is the bar, from the team's explainer guide — atom-level, every time:

  "Kako ste?"             → "Kako ${connector} how, ste ${connector} are-you — politely."
  "Običnu, molim."        → "Običnu ${connector} regular, molim ${connector} please — literally 'I ask'."
  "Iz Splita sam"         → "Iz ${connector} from, Splita is Split, sam ${connector} I am — so 'from Split I am'."
  "Onda kilogram rajčica" → "Onda ${connector} then, kilogram ${connector} a kilo, rajčica ${connector} of tomatoes."
  "Izvolite"              → "Izvolite — a waiter's polite 'go ahead, what'll it be?'"
  "Dobro jutro"           → "Dobro ${connector} good, jutro ${connector} morning."

Two failure modes — avoid BOTH:

TOO BIG (clause-sized; the learner can map nothing inside it):
  { "chunk_target": "Ideš na posao", "chunk_known": "are you going to work" }
TOO SMALL (shredded to bare grammar-words with thin/awkward isolated glosses):
  { "chunk_target": "An bhfuil", "chunk_known": "are" },
  { "chunk_target": "tú",        "chunk_known": "you" },
  { "chunk_target": "ag dul",    "chunk_known": "going" }
RIGHT — each chunk has an honest, natural gloss; thin grammar-words merge up:
  { "chunk_target": "Ideš",        "chunk_known": "you're going" },
  { "chunk_target": "na posao",    "chunk_known": "to work" }
and for "An bhfuil tú ag dul chun oibre?":
  { "chunk_target": "An bhfuil tú ag dul", "chunk_known": "are you going" },
  { "chunk_target": "chun oibre",           "chunk_known": "to work" }

================  WORKED EXAMPLES  ================

EXAMPLE A — plain multi-chunk, no tail:
  target "Buona sera"  known "Good afternoon"
  {
    "id": "...",
    "decomposition": [
      { "chunk_target": "buona", "chunk_known": "good" },
      { "chunk_target": "sera",  "chunk_known": "afternoon" }
    ],
    "explainer_text": "buona ${connector} good, sera ${connector} afternoon"
  }

EXAMPLE B — word-by-word would mislead, so a tail is added:
  target "Iz Splita sam"  known "I'm from Split"
  {
    "id": "...",
    "decomposition": [
      { "chunk_target": "Iz",     "chunk_known": "from" },
      { "chunk_target": "Splita", "chunk_known": "Split" },
      { "chunk_target": "sam",    "chunk_known": "I am" }
    ],
    "literal": "from Split I am",
    "explainer_text": "iz ${connector} from, sam ${connector} I am — so 'from Split I am'"
  }
  (Split is a place name; here it is load-bearing to the literal reading so it
   stays, but it is not glossed as a translation.)

EXAMPLE C — fixed single word, usage note:
  target "Izvolite"  known "What can I get you?"
  {
    "id": "...",
    "decomposition": [
      { "chunk_target": "Izvolite", "chunk_known": "a waiter's polite 'go ahead, what'll it be?'" }
    ],
    "explainer_text": "Izvolite — a waiter's polite 'go ahead, what'll it be?'"
  }

EXAMPLE D — form does a job (gloss as the job, no grammar word):
  target "kilogram rajčica"  known "a kilo of tomatoes"
  {
    "id": "...",
    "decomposition": [
      { "chunk_target": "kilogram", "chunk_known": "a kilo" },
      { "chunk_target": "rajčica",  "chunk_known": "of tomatoes" }
    ],
    "explainer_text": "kilogram ${connector} a kilo, rajčica ${connector} of tomatoes"
  }

EXAMPLE E — skip (single ordinary chunk, no misleading order, no usage note):
  target "Zanimljivo"  known "How interesting"
  { "id": "...", "decomposition": [], "explainer_text": "" }

================  INPUT  ================
${inputBlock}

OUTPUT: a JSON array, one object per input sentence IN THE SAME ORDER, each with
"id", "decomposition", and "explainer_text" (plus optional "literal" on chunks /
"primitives" where the rule calls for them). Output ONLY the JSON array — no
prose, no markdown, no code fences.`
}

/**
 * Parse the model's batch response into a Map of id → result. Tolerant of
 * accidental code fences. Skips entries that are structurally broken — the
 * caller treats those as failures and surfaces them per-row.
 */
function parseBatchResponse(raw) {
  if (!raw || typeof raw !== 'string') {
    throw new Error('Empty model response')
  }
  const m = raw.match(/\[[\s\S]*\]/)
  if (!m) throw new Error('No JSON array found in model response')
  let parsed
  try {
    parsed = JSON.parse(m[0])
  } catch (e) {
    throw new Error(`Invalid JSON array from model: ${e.message}`)
  }
  if (!Array.isArray(parsed)) {
    throw new Error('Model response is not an array')
  }
  const byId = new Map()
  for (const entry of parsed) {
    if (!entry || typeof entry.id !== 'string') continue
    if (!Array.isArray(entry.decomposition)) continue
    if (typeof entry.explainer_text !== 'string') continue
    let bad = false
    for (const e of entry.decomposition) {
      if (
        !e ||
        typeof e.chunk_target !== 'string' ||
        typeof e.chunk_known !== 'string'
      ) {
        bad = true
        break
      }
    }
    if (bad) continue
    // Empty decomposition + empty explainer_text is a valid result for
    // sentences that consist entirely of proper nouns (names, places).
    // Stage-1 player skips the slot when explainer_audio_id is NULL, so
    // an empty text means "no explainer needed for this sentence".
    //
    // The decomposition column is jsonb, so we additively pass through the
    // optional per-chunk `literal` (string) and `primitives` ([{target,known}])
    // when the model supplies them. Malformed primitives are dropped rather
    // than failing the row; the core chunk_target/chunk_known pair is always
    // preserved so existing readers keep working unchanged.
    byId.set(entry.id, {
      decomposition: entry.decomposition.map(e => {
        const chunk = {
          chunk_target: e.chunk_target,
          chunk_known: e.chunk_known,
        }
        if (typeof e.literal === 'string' && e.literal.trim()) {
          chunk.literal = e.literal.trim()
        }
        if (Array.isArray(e.primitives)) {
          const prims = e.primitives
            .filter(p => p && typeof p.target === 'string' && typeof p.known === 'string')
            .map(p => ({ target: p.target, known: p.known }))
          if (prims.length) chunk.primitives = prims
        }
        return chunk
      }),
      explainer_text: entry.explainer_text.trim(),
    })
  }
  return byId
}

// =============================================================================
// PUBLIC API
// =============================================================================

/**
 * Generate explainer payload for a BATCH of sentences from the same course.
 * One CLI invocation handles up to ~15 sentences — the CLI startup cost
 * (~2-15s) is dominated by spawning the subprocess, not by the model work
 * itself, so amortising across many sentences is a ~10× speedup over
 * per-sentence calls.
 *
 * Returns a Map<id, { decomposition, explainer_text }>. The caller treats
 * any input id missing from the returned map as a per-row failure (rather
 * than failing the whole batch) so a single garbled JSON entry doesn't
 * stall an entire pod.
 *
 * Throws only on hard CLI failures or completely unparseable output.
 */
async function generateForBatch({ courseCode, sentences }) {
  if (!Array.isArray(sentences) || sentences.length === 0) return new Map()
  const { target, learner } = parseCourseCode(courseCode)
  const connector = getConnectorForLearnerLang(learner)
  const prompt = buildBatchPrompt({
    sentences,
    targetLang: target,
    learnerLang: learner,
    connector,
  })
  // Default Haiku for cost/speed. EXPLAINER_MODEL=sonnet lets the
  // overnight runner escalate when Haiku struggles on a particular
  // language's batches (Japanese / Korean explainer prompts have a
  // higher failure rate, likely from JSON-array escaping around CJK
  // characters in the model's response).
  //
  // Timeout: claudeChat defaults to 120s — fine for Haiku on Latin
  // batches, too tight for Sonnet on a 12-sentence CJK batch where
  // the JSON output alone runs 3-4k tokens. Bump to 5 minutes so
  // legitimate slow generations complete instead of getting SIGTERM'd
  // with a useless 'Command failed' error.
  const raw = await claudeChat(prompt, {
    model: process.env.EXPLAINER_MODEL || 'haiku',
    timeout: 5 * 60 * 1000,
  })
  return parseBatchResponse(raw)
}

module.exports = {
  generateForBatch,
  parseCourseCode,
  getConnectorForLearnerLang,
  shouldSkipCourse,
  // Exported for unit testing without needing the CLI.
  _internal: { buildBatchPrompt, parseBatchResponse },
}
